<?php
declare(strict_types=1);
namespace App\Tests;
use Symfony\Bundle\FrameworkBundle\Test\WebTestCase;
final class CustomerFormTest extends WebTestCase
{
    public function testCustomerListOpens(): void { $client=static::createClient(); $client->request('GET','/customers'); self::assertResponseIsSuccessful(); self::assertSelectorTextContains('h1','Клиенты'); }
    public function testNewCustomerFormOpens(): void { $client=static::createClient(); $client->request('GET','/customers/new'); self::assertResponseIsSuccessful(); self::assertSelectorExists('input[name="customer[name]"]'); }
    public function testSuccessfulCreationRedirectsAndShowsFlash(): void { $client=static::createClient(); $crawler=$client->request('GET','/customers/new'); $form=$crawler->selectButton('Сохранить клиента')->form(['customer[name]'=>'Мария Тестова','customer[email]'=>'maria@example.test','customer[phone]'=>'+7 900 000-00-00','customer[company]'=>'Example','customer[comment]'=>'Тест']); $client->submit($form); self::assertResponseRedirects('/customers'); $client->followRedirect(); self::assertSelectorTextContains('.flash','Клиент успешно создан.'); }
    public function testBlankNameIsRejected(): void { $client=static::createClient(); $crawler=$client->request('GET','/customers/new'); $form=$crawler->selectButton('Сохранить клиента')->form(['customer[name]'=>'','customer[email]'=>'ok@example.test']); $client->submit($form); self::assertResponseIsSuccessful(); self::assertSelectorTextContains('body','Укажите имя клиента.'); }
    public function testInvalidEmailIsRejected(): void { $client=static::createClient(); $crawler=$client->request('GET','/customers/new'); $form=$crawler->selectButton('Сохранить клиента')->form(['customer[name]'=>'Тест','customer[email]'=>'not-an-email']); $client->submit($form); self::assertResponseIsSuccessful(); self::assertSelectorTextContains('body','Введите корректный email.'); }
    public function testTooLongCommentIsRejected(): void { $client=static::createClient(); $crawler=$client->request('GET','/customers/new'); $form=$crawler->selectButton('Сохранить клиента')->form(['customer[name]'=>'Тест','customer[email]'=>'ok@example.test','customer[comment]'=>str_repeat('x',1001)]); $client->submit($form); self::assertResponseIsSuccessful(); self::assertSelectorTextContains('body','Комментарий не должен превышать 1000 символов.'); }
    public function testCsrfTokenIsRequired(): void { $client=static::createClient(); $client->request('POST','/customers/new',['customer'=>['_token'=>'invalid','name'=>'Тест','email'=>'ok@example.test']]); self::assertResponseIsSuccessful(); self::assertSelectorExists('.form-errors'); }
    public function testUserHtmlIsEscaped(): void { $client=static::createClient(); $crawler=$client->request('GET','/customers/new'); $form=$crawler->selectButton('Сохранить клиента')->form(['customer[name]'=>'<script>alert(1)</script>','customer[email]'=>'xss@example.test']); $client->submit($form); self::assertResponseRedirects('/customers'); $client->followRedirect(); self::assertSelectorExists('table'); self::assertSelectorTextContains('table','<script>alert(1)</script>'); self::assertSelectorNotExists('table script'); }
}
